/** One exact email test-contract repair installation through unchanged native guards. Never a full PASS. */
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {isDeepStrictEqual} from 'node:util';
import {EMAIL,EMAIL_REPAIRED_FILES} from './email-repair-source.mjs';
import {installHash,installJson,INSTALL_BUILD_FIELDS,validateInstallGrant} from './ci-install-grant.mjs';
import {CI_POLICY} from './policy-version.mjs';
import {inspectEmailRepairBuildOnlySnapshot} from './build-only-evidence.mjs';
export function createEmailInstallGrant({acceptance,evidence,snapshot,baselineBuildId,environmentSha256,now=Date.now()}){
 const {acceptanceSha256,...body}=acceptance??{};
 assert(acceptanceSha256===installHash(installJson(body))&&body.kind==='COMBINED_EMAIL_FULL_RUN_AND_TEST_CONTRACT_REPAIR'&&body.policy==='email-test-contract-repair/v1'&&body.result==='ACCEPTED_WITH_AUTHENTICATED_ORIGINAL_PASSES'&&body.candidate===EMAIL.candidate&&body.original===EMAIL.original&&body.originalRun?.runId===EMAIL.fullRun&&body.originalRun.conclusion==='failure'&&body.fullGatePassCreated===false&&body.createsNewFullPassBaseline===false&&body.releaseAuthorized===false&&body.postDeployAcceptanceRequired===true,'Complete explicit email retained-evidence acceptance required');
 assert.deepEqual(body.originalFailures?.map(f=>f.path).sort(),EMAIL_REPAIRED_FILES,'Exact original failed files must remain visible');
 const passing=rows=>rows.every(f=>f.state==='PASSED'&&f.failedAssertions===0&&Number.isSafeInteger(f.passingAssertions)&&f.passingAssertions>0);
 assert(body.ordinaryFiles?.length===2041&&new Set(body.ordinaryFiles.map(f=>f.path)).size===2041&&passing(body.ordinaryFiles),'Complete actual ordinary inventory required');
 const replaced=body.ordinaryFiles.filter(f=>f.originCandidate===EMAIL.candidate);assert.deepEqual(replaced.map(f=>f.path).sort(),EMAIL_REPAIRED_FILES);assert(replaced.every(f=>f.origin?.runId===EMAIL.repairRun));
 assert(body.ordinaryFiles.filter(f=>!EMAIL_REPAIRED_FILES.includes(f.path)).every(f=>f.originCandidate===EMAIL.original),'Unchanged ordinary origins must remain original');
 assert(body.browserFiles?.length===60&&new Set(body.browserFiles.map(f=>f.engine+'\0'+f.path)).size===60&&passing(body.browserFiles)&&body.browserFiles.every(f=>f.originCandidate===EMAIL.original),'Complete original browser inventory required');
 const paths=body.browserFiles.filter(f=>f.engine==='chromium').map(f=>f.path).sort();assert.equal(paths.length,20);for(const engine of ['chromium','firefox','webkit'])assert.deepEqual(body.browserFiles.filter(f=>f.engine===engine).map(f=>f.path).sort(),paths);
 assert(body.wholeCompiler?.kind==='AUTHENTICATED_EMAIL_REPAIR_WHOLE_COMPILER'&&body.wholeCompiler.candidate===EMAIL.candidate&&body.wholeCompiler.runId===EMAIL.compilerRun&&body.wholeCompiler.controller===EMAIL.compilerController&&body.wholeCompiler.conclusion==='success'&&isDeepStrictEqual(body.wholeCompiler.runtime,{node:'22.23.3',platform:'linux',arch:'x64'}),'Fresh exact repaired-source compiler required');
 assert(evidence.kind==='AUTHENTICATED_EMAIL_TEST_REPAIR_AND_CANONICAL_BUILD'&&evidence.sha===EMAIL.candidate&&evidence.controller===EMAIL.buildController&&evidence.controllerBranch==='alpha'&&evidence.runId===EMAIL.buildRun&&evidence.baseline===EMAIL.ciBaseline&&evidence.deploymentBaseline===EMAIL.bonus&&evidence.build?.canonicalCandidateInputsVerified===true&&evidence.build.source===EMAIL.candidate&&evidence.build.controller===EMAIL.buildController&&evidence.build.runId===EMAIL.buildRun,'Exact email canonical bytes and actual Bonus baseline required');
 const {proofSha256,...boundary}=evidence.baselineAdvance??{};assert(proofSha256===installHash(installJson(boundary))&&boundary.kind==='FORWARD_STAGING_BASELINE_SOURCE_PREFIX_NOT_CI_RECEIPT'&&boundary.candidate===EMAIL.candidate&&boundary.ciBaseline===EMAIL.ciBaseline&&boundary.deploymentBaseline===EMAIL.bonus&&boundary.ciMigrationCount===498&&boundary.deploymentMigrationCount===503&&boundary.candidateMigrationCount===504&&boundary.originalCiBaselinePreserved===true&&boundary.requiresFreshActualLedgerAndBuildBinding===true&&boundary.releaseAuthorized===false,'Actual unchanged 503-prefix and one new migration required');
 const inventory=inspectEmailRepairBuildOnlySnapshot({...snapshot,expected:{candidate:EMAIL.candidate,controller:EMAIL.buildController,runId:EMAIL.buildRun},now});assert(evidence.artifact.id===inventory.artifact.id&&evidence.artifact.digest===inventory.artifact.digest,'Canonical original artifact differs');
 const run=snapshot.run,producer=inventory.producer,witnessFingerprint=installHash(installJson({kind:'EMAIL_RETAINED_FULL_AND_TEST_CONTRACT_REPAIR_INSTALL',acceptanceSha256,sourceProofSha256:body.sourceProofSha256,runId:run.id,source:EMAIL.candidate,controller:EMAIL.buildController,artifact:evidence.artifact,provenanceSha256:evidence.build.provenanceSha256}));
 return validateInstallGrant({format:1,kind:'OPERATOR_AUTHORIZED_STAGING_CI_BUILD_INSTALL',policyVersion:CI_POLICY,target:'alpha-staging',installId:randomUUID(),source:EMAIL.candidate,controller:EMAIL.buildController,controllerBranch:'alpha',baseline:EMAIL.bonus,baselineBuildId,environmentSha256,runId:run.id,runAttempt:1,runCreatedAt:run.created_at,issuedAt:new Date(now).toISOString(),expiresAt:new Date(Math.min(now+30*60000,Date.parse(run.created_at)+86400000)).toISOString(),producerStartedAt:producer.started_at,producerCompletedAt:producer.completed_at,witnessFingerprint,artifact:evidence.artifact,build:Object.fromEntries(INSTALL_BUILD_FIELDS.map(k=>[k,evidence.build[k]]))},{now});
}
